"},"$:/plugins/bj/unieditor/ui-tweaks.css":{"title":"$:/plugins/bj/unieditor/ui-tweaks.css","tags":"$:/tags/Stylesheet","text":"/* UniEditor UI tweaks: border, background, hide scrollbars */

.unieditor {
	border: 1.5px solid <<colour primary>>;
	border-radius: 4px;
	background: <<colour tiddler-editor-fields-odd>>;
}
.unieditor textarea,
.unieditor textarea.unieditor__textarea,
.unieditor textarea.unieditor_controlwrap {
	caret-color: <<colour primary>> !important;
}

/* Ensure uniform word wrapping between textarea and display layers to prevent cursor desync */
.unieditor textarea,
.unieditor textarea.unieditor__textarea,
.unieditor textarea.unieditor_controlwrap,
.unieditor canvas,
.unieditor .textlayer {
	white-space: pre-wrap !important;
	word-wrap: break-word !important;
	overflow-wrap: break-word !important;
	word-break: break-word !important;
}

/* Override upstream .overflowy { overflow-y: scroll !important } —
   the textarea auto-expands so forced scroll is just visual clutter. */
.unieditor .overflowy {
	overflow-y: auto !important;
	scrollbar-width: none !important;
	-ms-overflow-style: none !important;
}
.unieditor .overflowy::-webkit-scrollbar {
	display: none !important;
}

/* --- Floating preview toggle button --- */
.uni-preview-toggle {
	position: absolute !important;
	top: 4px !important;
	right: 4px !important;
	left: auto !important;
	z-index: 10;
	background: transparent;
	border: none;
	cursor: pointer;
	opacity: 0.25;
	padding: 2px;
	width: 22px !important;
	height: 22px !important;
	line-height: 0;
	transition: opacity 0.2s ease;
}
.uni-preview-toggle:hover {
	opacity: 0.8;
}
.uni-preview-toggle p {
	margin: 0;
	padding: 0;
	line-height: 0;
}
